import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaAvaliacao = () => {
  const { id } = useParams();
  const [cursos, setCursos] = useState([]);
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [submissoes, setSubmissoes] = useState([]);
  const [novaAvaliacao, setNovaAvaliacao] = useState({
    titulo: "",
    descricao: "",
    dataInicio: "",
    dataFim: "",
    pontuacaoMaxima: 20,
    cursoId: "",
    tipo: "escolha_multipla",
    perguntas: [
      {
        texto: "",
        opcoes: ["", "", "", ""],
        respostaCorreta: 0,
      },
    ],
  });
  const [carregando, setCarregando] = useState(true);

  const fetchAvaliacoes = async () => {
    try {
      const avaliacoesRes = await private_api.get(
        `/professores/${id}/avaliacoes`
      );
      setAvaliacoes(avaliacoesRes.data);

      // Extrair todas as submissões
      const todasSubmissoes = avaliacoesRes.data.flatMap((avaliacao) =>
        avaliacao.submissoes.map((submissao) => ({
          ...submissao,
          avaliacaoTitulo: avaliacao.titulo,
          cursoNome: avaliacao.curso?.nome || "N/A",
        }))
      );

      setSubmissoes(todasSubmissoes);
    } catch (error) {
      console.error("Erro ao carregar avaliações:", error);
    } finally {
      setCarregando(false);
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      try {
        setCarregando(true);
        // Carrega cursos
        const cursosRes = await private_api.get(
          `/professores/${id}/listacursos`
        );
        setCursos(cursosRes.data);

        // Carrega avaliações
        await fetchAvaliacoes();
      } catch (error) {
        console.error("Erro ao carregar dados:", error);
        setCarregando(false);
      }
    };

    fetchData();

    // Configura polling para atualizar a cada 30 segundos
    const interval = setInterval(fetchAvaliacoes, 30000);
    return () => clearInterval(interval);
  }, [id]);

  // ... (manter todos os outros manipuladores e funções existentes)

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      {/* ... (manter toda a parte superior do código até a seção de avaliações submetidas) */}

      <div className="bg-white p-3 rounded shadow w-75">
        <div className="d-flex justify-content-between align-items-center mb-3">
          <h4 className="mb-0">Submissões dos Alunos</h4>
          <div>
            <span className="badge bg-primary me-2">
              {submissoes.length} submissões
            </span>
            {carregando && (
              <div
                className="spinner-border spinner-border-sm text-primary"
                role="status"
              >
                <span className="visually-hidden">Carregando...</span>
              </div>
            )}
          </div>
        </div>

        {carregando && submissoes.length === 0 ? (
          <div className="text-center my-4">
            <div className="spinner-border text-primary" role="status">
              <span className="visually-hidden">Carregando...</span>
            </div>
          </div>
        ) : submissoes.length > 0 ? (
          <div className="table-responsive">
            <table className="table table-bordered table-hover">
              <thead className="table-light">
                <tr>
                  <th>Aluno</th>
                  <th>Avaliação</th>
                  <th>Curso</th>
                  <th>Pontuação</th>
                  <th>Tempo</th>
                  <th>Entregue em</th>
                  <th>Respostas</th>
                </tr>
              </thead>
              <tbody>
                {submissoes.map((submissao, index) => (
                  <tr key={index}>
                    <td>{submissao.aluno?.utilizador?.nome || "N/A"}</td>
                    <td>{submissao.avaliacaoTitulo}</td>
                    <td>{submissao.cursoNome}</td>
                    <td>{submissao.pontuacao}</td>
                    <td>{submissao.tempo}</td>
                    <td>
                      {new Date(submissao.dataSubmissao).toLocaleString()}
                    </td>
                    <td>
                      <button
                        className="btn btn-sm btn-outline-primary"
                        onClick={() => {
                          // Aqui você pode implementar a lógica para ver as respostas detalhadas
                          console.log(submissao.respostas);
                          alert(JSON.stringify(submissao.respostas, null, 2));
                        }}
                      >
                        Ver Respostas
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="alert alert-info">
            Nenhuma submissão de avaliação encontrada
          </div>
        )}
      </div>
    </div>
  );
};

export default LecionaAvaliacao;
